  # Headless mode — within-company CLI fallback routing (cycle-104 Sprint 2)
  # ---------------------------------------------------------------------------
  # Routes between HTTP API adapters and local CLI binaries (`claude` /
  # `codex` / `gemini`). Per-call override via env: LOA_HEADLESS_MODE=<mode>
  # (env wins over this config; both unset → prefer-api).
  #
  # Modes (chain_resolver.resolve() applies them within-company only):
  #   prefer-api : HTTP first, CLI last in each chain entry (today's default)
  #   prefer-cli : CLI first, HTTP last (budget-constrained operators)
  #   api-only   : drop CLI entries from chain
  #   cli-only   : drop HTTP entries — zero-API-key path. Requires every
  #                primary in your bindings to have a `kind: cli` chain
  #                terminal (`claude-headless` / `codex-headless` /
  #                `gemini-headless` in the default model-config.yaml).
  #
  # CLI binaries must be on $PATH (or pin paths below). The router REFUSES
  # to issue HTTPS when the resolved chain is CLI-only (defense-in-depth,
  # SDD §1.9). Operator runbooks (cycle-104 T2.12):
  #   grimoires/loa/runbooks/headless-mode.md            # 4-mode reference
  #   grimoires/loa/runbooks/headless-capability-matrix.md  # feature × adapter
  #   grimoires/loa/runbooks/chain-walk-debugging.md     # LOA_HEADLESS_VERBOSE + envelope queries
  headless:
    mode: prefer-api                         # prefer-api | prefer-cli | api-only | cli-only
    # agy_opt_in: the agy (Antigravity) CLI route — the `gemini-headless` hop — is opt-in (cycle-127).
    # Off (the default), cheval refuses an agy dispatch before any spawn and every planner (dissent,
    # Flatline tertiary, Bridgebuilder, /loa, run preflight) records the hop as not planned
    # (reason opt_in_required), never as a failed voice — a host without agy plans no Google CLI voice.
    # Set true only where agy is installed AND OAuth-authed: `agy -p` takes the whole prompt (the
    # redacted review diff) on argv, readable by every local account through /proc and ps. Only a
    # YAML boolean true counts; there is no environment override.
    agy_opt_in: false
    # cli_paths: discovery hints. If unset, $PATH is searched.
    # cli_paths:
    #   claude: /usr/local/bin/claude
    #   codex: /usr/local/bin/codex
    #   gemini: /usr/local/bin/gemini

  # Provider registry — override endpoints, auth, or add new providers
  # Providers not listed here use system defaults from model-config.yaml
  providers:
    openai:
      if (saved === undefined) delete process.env.LOA_HEADLESS_MODE; else process.env.LOA_HEADLESS_MODE = saved;
      delete process.env.LOA_AGY_OPT_IN;
    }
  });
});

describe("isAgyRouted", () => {
  it("the gemini-headless id is agy on any mode; a google model is agy under cli-only only; other providers never", () => {
    assert.equal(isAgyRouted("google", "gemini-headless", "prefer-api"), true);
    assert.equal(isAgyRouted("google", "gemini-3.1-pro-preview", "cli-only"), true);
    assert.equal(isAgyRouted("google", "gemini-3.1-pro-preview", "prefer-api"), false);
    assert.equal(isAgyRouted("google", "gemini-3.1-pro-preview", "prefer-cli"), false);
    assert.equal(isAgyRouted("anthropic", "claude-headless", "cli-only"), false);
    assert.equal(isAgyRouted("openai", "gpt-5.5-pro", "cli-only"), false);
  });
});

describe("validateApiKeys with the agy gate", () => {
  const models = MultiModelConfigSchema.parse({
